	'rates_inc2_v' => 'Fester Schreibtisch, 1 Gbps Glasfaser, Telefonkabinen, Meetingraum',
	'rates_inc_label' => 'In jedem Aufenthalt inbegriffen',
	'rates_intro' => 'Transparente Preise für Wochen- und Monatsaufenthalte – wöchentliche Reinigung, tägliches Frühstück und ein eigener Arbeitsbereich sind immer inbegriffen.',
	'rates_label' => 'Preise',
